<dialog class="book-welcome" data-book-welcome aria-labelledby="book-welcome-title"><form method="dialog" class="book-welcome__inner" data-book-welcome-form><p class="book-kicker">ARCHON PUBLISHING HOUSE</p><h1 id="book-welcome-title" data-book-welcome-title>Every remarkable book begins with a name.</h1><p data-book-welcome-message>What name should appear on your story?</p><label for="book-visitor-name">Your name</label><input id="book-visitor-name" name="visitor_name" type="text" autocomplete="name" minlength="2" maxlength="60" aria-describedby="book-name-help book-name-error" data-book-name-input><small id="book-name-help">This stays on this device only.</small><p class="book-form-error" id="book-name-error" role="alert" data-book-name-error></p><div class="book-welcome__actions"><button class="book-action" value="begin" type="submit" data-book-begin>Begin My Story</button><button class="book-guest" value="guest" type="submit" data-book-guest>Continue as Guest</button></div></form></dialog>
